function findText(obj) {
  const textFromOutput = obj.output?.[0]?.content?.[0]?.text;
  if (typeof textFromOutput === "string" && textFromOutput.trim()) {
    return textFromOutput;
  }

  if (typeof obj.text === "string" && obj.text.trim()) return obj.text;
  if (typeof obj.content === "string" && obj.content.trim()) return obj.content;
  if (typeof obj.message === "string" && obj.message.trim()) return obj.message;

  throw new Error("LLM text output not found");
}

function extractJson(rawText) {
  let text = rawText.trim();

  text = text
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();

  const firstBrace = text.indexOf("{");
  const lastBrace = text.lastIndexOf("}");

  if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
    throw new Error("Could not find JSON object in LLM output");
  }

  const jsonText = text.slice(firstBrace, lastBrace + 1);

  try {
    return JSON.parse(jsonText);
  } catch (error) {
    throw new Error(`Failed to parse JSON from LLM output: ${error.message}`);
  }
}

const rawText = findText(item);
const parsed = extractJson(rawText);

